import { NextResponse } from 'next/server';
import { createServiceSupabaseClient } from '@/runtime/supabase/server';
export const dynamic='force-dynamic';
function gate(req:Request,scope:string){const token=req.headers.get('authorization')?.replace(/^Bearer\s+/i,'').trim();if(!token)return false;try{const map=JSON.parse(process.env.SFI_EXTERNAL_API_KEYS_JSON||'{}') as Record<string,{scopes?:string[]}>;return Boolean(map[token]?.scopes?.includes(scope)||map[token]?.scopes?.includes('*'));}catch{return false}}
export async function POST(req:Request){if(!gate(req,'observe'))return NextResponse.json({ok:false,error:'unauthorized'},{status:401});const body=await req.json().catch(()=>({})) as Record<string,unknown>;const surface=String(body.surface||'proposals');const db=createServiceSupabaseClient();if(surface==='proposals'){const r=await db.from('action_proposals').select('id,title,status,risk_level,approval_required,created_at,expected_field_delta').order('created_at',{ascending:false}).limit(50);return NextResponse.json({ok:!r.error,data:r.data||[],error:r.error?.message||null});}if(surface==='evidence'){const r=await db.from('sfi_evidence_ledger').select('*').order('created_at',{ascending:false}).limit(50);return NextResponse.json({ok:!r.error,data:r.data||[],error:r.error?.message||null});}return NextResponse.json({ok:false,error:'surface_not_allowed',allowed:['proposals','evidence']},{status:400});}
